import pytest
from solution import lateralsuface_cylinder


def test_issue_example_10_5():
    """Example: lateralsuface_cylinder(10,5)==314.15000000000003."""
    assert lateralsuface_cylinder(10, 5) == 314.15000000000003  # 2*3.1415*10*5 = 314.15


def test_issue_unit_cylinder():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(1, 1) == pytest.approx(6.283)  # 2*3.1415*1*1 = 6.283


def test_issue_zero_radius():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(0, 5) == 0.0  # 2*3.1415*0*5 = 0.0


def test_issue_zero_height():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(10, 0) == 0.0  # 2*3.1415*10*0 = 0.0


def test_issue_zero_both():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(0, 0) == 0.0  # 2*3.1415*0*0 = 0.0


def test_issue_double_radius_doubles_area():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(20, 5) == pytest.approx(628.3)  # 2*3.1415*20*5 = 628.3


def test_issue_swapped_dimensions():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(5, 10) == pytest.approx(314.15000000000003)  # 2*3.1415*5*10 = 314.15


def test_issue_fractional_dimensions():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(2.5, 4.0) == pytest.approx(62.83)  # 2*3.1415*2.5*4.0 = 62.83


def test_issue_small_integers():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(2, 3) == pytest.approx(37.698)  # 2*3.1415*2*3 = 37.698


def test_issue_height_scaling():
    """Lateral surface area of a cylinder is 2*pi*r*h."""
    assert lateralsuface_cylinder(1, 5) == pytest.approx(31.415)  # 2*3.1415*1*5 = 31.415


def test_contract_returns_number():
    """Write a function to find the lateral surface area of a cylinder."""
    assert isinstance(lateralsuface_cylinder(10, 5), (int, float))


def test_contract_takes_r_and_h():
    """Implement lateralsuface_cylinder(r, h) in solution.py."""
    assert lateralsuface_cylinder(r=10, h=5) == 314.15000000000003  # 2*3.1415*10*5 = 314.15
